std::array<int, 5> source = {10, 20, 30, 40, 50};

// Copy the full range of the source container
std::vector<int> v1(source.begin(), source.end());

// Copy a sub-range (first three elements)
std::vector<int> v2(
    source.begin(),
    source.begin() + 3
);

// Initialization from another vector's iterators (copy constructor style)
std::vector<int> v3(v1.cbegin(), v1.cend());
